mapper.select:
SELECT c.id AS customer_id, c.last_branch_id
FROM customers c
WHERE c.status = 'ACTIVE'
  AND EXISTS (SELECT 1 FROM push_subscriptions p WHERE p.customer_id = c.id)
  AND NOT EXISTS (SELECT 1 FROM deal_push_log l WHERE l.customer_id = c.id
                  AND (l.sent_on = #{today} OR l.sent_at >= #{dayStart}
                       OR (l.sent_at IS NULL AND l.dropped_at IS NULL)))
  AND c.id > #{after}
ORDER BY c.id
LIMIT #{limit}

mapper.update:
UPDATE deal_push_log SET sent_at = #{now}
WHERE announcement_id = #{announcementId} AND customer_id = #{customerId}
  AND sent_at IS NULL AND dropped_at IS NULL
